-- ============================================================
-- 制药公司核心业务数据库 pharma_db
-- 药品信息 / 库存管理 / 销售流水，供 DeepSearch Pro 做结构化检索
--
-- 数据规模：111 种药品 · 344 条库存批次 · 5799 条销售流水
-- 时间跨度：2025-08-01 ~ 2026-08-10（覆盖完整 12 个月 + 当月，可做同比/环比/趋势分析）
--
-- 模拟数据的设计（不是纯随机，为了让分析类查询能问出东西）：
--   · 季节性：呼吸/抗病毒/中成药冬季走高，抗过敏春季走高，慢病用药常年平稳
--   · 价格趋势：整体年降约 3%；部分品种自 2026-01 起进集采，单价下探 35%
--   · 销量分层：畅销 / 普通 / 长尾三档，符合医药销售的长尾分布
--   · 库存效期：含少量已过期批次，可用于做效期预警类查询
--
-- 注意：显式指定 utf8mb4，否则容器默认 latin1 时中文会变问号
-- ============================================================
CREATE DATABASE IF NOT EXISTS pharma_db
  DEFAULT CHARACTER SET utf8mb4
  DEFAULT COLLATE utf8mb4_unicode_ci;
USE pharma_db;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS sales_records;
DROP TABLE IF EXISTS inventory;
DROP TABLE IF EXISTS drugs;
SET FOREIGN_KEY_CHECKS = 1;

-- 1. 药品信息表
CREATE TABLE drugs (
    drug_id INT PRIMARY KEY AUTO_INCREMENT,
    generic_name VARCHAR(100) NOT NULL COMMENT '通用名，如 布洛芬缓释胶囊',
    brand_name VARCHAR(100) COMMENT '商品名，如 芬必得',
    approval_number VARCHAR(50) COMMENT '批准文号 国药准字H/Z/J...',
    specifications VARCHAR(100) COMMENT '规格，如 0.3g*20粒',
    dosage_form VARCHAR(50) COMMENT '剂型：片剂/胶囊剂/注射剂/颗粒剂等',
    manufacturer VARCHAR(100) COMMENT '生产厂家',
    therapeutic_area VARCHAR(50) COMMENT '治疗领域：心血管/抗生素/糖尿病等',
    description TEXT COMMENT '适应症描述',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_drugs_generic (generic_name),
    INDEX idx_drugs_brand (brand_name),
    INDEX idx_drugs_area (therapeutic_area)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='药品主数据';

-- 2. 库存表
CREATE TABLE inventory (
    inventory_id INT PRIMARY KEY AUTO_INCREMENT,
    drug_id INT NOT NULL,
    batch_number VARCHAR(50) NOT NULL COMMENT '生产批号',
    quantity_on_hand INT DEFAULT 0 COMMENT '当前库存量（盒/瓶/支）',
    warehouse_location VARCHAR(50) COMMENT '库位，如 A区-01架',
    production_date DATE COMMENT '生产日期',
    expiry_date DATE COMMENT '有效期至，用于效期预警',
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (drug_id) REFERENCES drugs(drug_id) ON DELETE CASCADE,
    INDEX idx_inventory_drug (drug_id),
    INDEX idx_inventory_expiry (expiry_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存批次';

-- 3. 销售流水表
CREATE TABLE sales_records (
    sale_id INT PRIMARY KEY AUTO_INCREMENT,
    drug_id INT NOT NULL,
    sale_date DATE NOT NULL COMMENT '销售日期',
    quantity_sold INT NOT NULL COMMENT '销售数量',
    unit_price DECIMAL(10,2) COMMENT '销售单价（元）',
    total_amount DECIMAL(15,2) COMMENT '销售总额（元）',
    customer_name VARCHAR(100) COMMENT '客户名称：医院或连锁药房',
    region VARCHAR(50) COMMENT '销售区域：华北/华东/华南/华中/西南/西北/东北',
    sales_rep VARCHAR(50) COMMENT '销售代表',
    FOREIGN KEY (drug_id) REFERENCES drugs(drug_id) ON DELETE CASCADE,
    INDEX idx_sales_drug_date (drug_id, sale_date),
    INDEX idx_sales_date (sale_date),
    INDEX idx_sales_region (region)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='销售流水';


-- ------------------------------------------------------------
-- 数据导入（关掉唯一性检查和自动提交，几千行也能秒进）
-- ------------------------------------------------------------
SET autocommit = 0;
SET unique_checks = 0;
SET foreign_key_checks = 0;

