-- ------------------------------------------------------------
-- 导入自检：跑完应该看到三张表都有数据，且销售日期覆盖到 2026-08
-- ------------------------------------------------------------
SELECT '药品' AS 表, COUNT(*) AS 行数 FROM drugs
UNION ALL SELECT '库存', COUNT(*) FROM inventory
UNION ALL SELECT '销售', COUNT(*) FROM sales_records;

SELECT MIN(sale_date) AS 最早, MAX(sale_date) AS 最晚,
       COUNT(*) AS 总笔数, ROUND(SUM(total_amount)/10000, 1) AS 总金额万元
FROM sales_records;

SELECT d.generic_name AS 药品, COUNT(*) AS 笔数,
       ROUND(SUM(s.total_amount)/10000, 1) AS 销售额万元
FROM sales_records s JOIN drugs d ON s.drug_id = d.drug_id
WHERE s.sale_date >= '2026-05-11'
GROUP BY d.generic_name ORDER BY 销售额万元 DESC LIMIT 10;
